package com.pousadamaretalta;

/**
 * Como o hóspede se identifica. Cada tipo escolhe o documento que recebe.
 * Um novo tipo (ex.: agência de turismo) é um novo record aqui, um novo
 * {@link DocumentTemplate} e uma entrada em {@link IdentityReader#ALL}.
 */
public interface GuestIdentity {
    DocumentTemplate template();

    default String cpf() { return null; }
    default String cnpj() { return null; }
    default String companyName() { return null; }
    default String passport() { return null; }
    default String country() { return null; }

    record Person(String cpf) implements GuestIdentity {
        public DocumentTemplate template() { return DocumentTemplate.COMPROVANTE; }
    }

    record Company(String cnpj, String companyName) implements GuestIdentity {
        public DocumentTemplate template() { return DocumentTemplate.FATURA; }
    }

    record Foreigner(String passport, String country) implements GuestIdentity {
        public DocumentTemplate template() { return DocumentTemplate.BOOKING_RECEIPT; }
    }
}
EOF
cat > IdentityReader.java <<'EOF'
package com.pousadamaretalta;

import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

/** Lê do corpo da requisição os campos de identificação; exige exatamente um conjunto. */
public final class IdentityReader {
    private record Kind(List<String> fields, Function<List<String>, GuestIdentity> build) {}

    private static final List<Kind> ALL = List.of(
            new Kind(List.of("guestCpf"), v -> new GuestIdentity.Person(v.get(0))),
            new Kind(List.of("companyCnpj", "companyName"), v -> new GuestIdentity.Company(v.get(0), v.get(1))),
            new Kind(List.of("guestPassport", "guestCountry"), v -> new GuestIdentity.Foreigner(v.get(0), v.get(1))));

    private IdentityReader() {}

    public static GuestIdentity read(JsonNode body) {
        GuestIdentity found = null;
        for (Kind kind : ALL) {
            List<String> values = new ArrayList<>();
            int present = 0;
            for (String f : kind.fields()) {
                String v = Json.optionalText(body, f);
                if (v != null) present++;
                values.add(v);
            }
            if (present == 0) continue;
            if (present != kind.fields().size() || found != null) {
                throw ApiException.invalid("Informe apenas um modo de identificação completo: guestCpf, "
                        + "companyCnpj + companyName, ou guestPassport + guestCountry");
            }
            found = kind.build().apply(values);
        }
        if (found == null) {
            throw ApiException.invalid("Identificação ausente: informe guestCpf, companyCnpj + companyName, "
                    + "ou guestPassport + guestCountry");
        }
        return found;
    }
}
EOF
cat > Json.java <<'EOF'
package com.pousadamaretalta;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;

public final class Json {
    public static final ObjectMapper MAPPER = new ObjectMapper();

    private Json() {}

    public static JsonNode parseObject(String body) {
        try {
            JsonNode n = MAPPER.readTree(body);
            if (n == null || !n.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
            return n;
        } catch (ApiException e) {
            throw e;
        } catch (Exception e) {
            throw ApiException.invalid("O corpo não é um JSON válido");
        }
    }

    /** Texto não vazio; null se ausente/null/vazio; 400 se não for texto. */
    public static String optionalText(JsonNode body, String field) {
        JsonNode n = body.get(field);
        if (n == null || n.isNull()) return null;
        if (!n.isTextual()) throw ApiException.invalid("O campo " + field + " deve ser texto");
        String s = n.asText().trim();
        return s.isEmpty() ? null : s;
    }

    public static String requiredText(JsonNode body, String field) {
        String s = optionalText(body, field);
        if (s == null) throw ApiException.invalid("O campo " + field + " é obrigatório");
        return s;
    }

    public static LocalDate requiredDate(JsonNode body, String field) {
        String s = requiredText(body, field);
        try {
            return LocalDate.parse(s);
        } catch (DateTimeParseException e) {
            throw ApiException.invalid("O campo " + field + " deve estar no formato AAAA-MM-DD");
        }
    }

    public static int requiredInt(JsonNode body, String field) {
        JsonNode n = body.get(field);
        if (n == null || n.isNull()) throw ApiException.invalid("O campo " + field + " é obrigatório");
        if (!n.isIntegralNumber() || !n.canConvertToInt()) {
            throw ApiException.invalid("O campo " + field + " deve ser um número inteiro");
        }
        return n.asInt();
    }
}
EOF
cat > DocumentTemplate.java <<'EOF'
package com.pousadamaretalta;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/** Texto e título do documento emitido para uma reserva paga. */
public interface DocumentTemplate {
    String title();

    String render(ReservationDocument d);

    DocumentTemplate COMPROVANTE = new DocumentTemplate() {
        public String title() { return "Comprovante de reserva"; }

        public String render(ReservationDocument d) {
            List<String> l = new ArrayList<>();
            l.add(title() + " nº " + d.reservationId());
            l.add("Hóspede: " + d.guestName() + " (CPF " + d.identity().cpf() + ")");
            ptBody(l, d);
            return String.join("\n", l);
        }
    };

    DocumentTemplate FATURA = new DocumentTemplate() {
        public String title() { return "Fatura de hospedagem"; }

        public String render(ReservationDocument d) {
            List<String> l = new ArrayList<>();
            l.add(title() + " nº " + d.reservationId());
            l.add("Empresa: " + d.identity().companyName() + " (CNPJ " + d.identity().cnpj() + ")");
            l.add("Hóspede: " + d.guestName());
            ptBody(l, d);
            l.add("ISS retido (5%): " + Money.brl(Money.round(d.total().multiply(new java.math.BigDecimal("0.05")))));
            return String.join("\n", l);
        }
    };

    DocumentTemplate BOOKING_RECEIPT = new DocumentTemplate() {
        public String title() { return "Booking receipt"; }

        public String render(ReservationDocument d) {
            DateTimeFormatter iso = DateTimeFormatter.ISO_LOCAL_DATE;
            List<String> l = new ArrayList<>();
            l.add(title() + " no. " + d.reservationId());
            l.add("Guest: " + d.guestName() + " (passport " + d.identity().passport() + ", "
                    + d.identity().country() + ")");
            l.add("Room: " + d.roomNumber() + " (" + d.roomType() + ")");
            l.add("Check-in: " + iso.format(d.checkIn()) + " | Check-out: " + iso.format(d.checkOut())
                    + " | " + d.nights() + (d.nights() == 1 ? " night" : " nights"));
            l.add("Nights: " + Money.brlEn(d.subtotal()));
            if (d.discount().signum() > 0) l.add("Discount: " + Money.brlEn(d.discount()));
            l.add("Total: " + Money.brlEn(d.total()));
            return String.join("\n", l);
        }
    };

    /** Linhas em português comuns ao comprovante e à fatura: quarto, datas, diárias, desconto, total. */
    private static void ptBody(List<String> l, ReservationDocument d) {
        DateTimeFormatter br = DateTimeFormatter.ofPattern("dd/MM/yyyy");
        l.add("Quarto: " + d.roomNumber() + " (" + d.roomType() + ")");
        l.add("Entrada: " + br.format(d.checkIn()) + " | Saída: " + br.format(d.checkOut())
                + " | " + d.nights() + (d.nights() == 1 ? " diária" : " diárias"));
        l.add("Diárias: " + Money.brl(d.subtotal()));
        if (d.discount().signum() > 0) l.add("Desconto: " + Money.brl(d.discount()));
        l.add("Total: " + Money.brl(d.total()));
    }
}
EOF
