        assertEquals(400, call("GET", "/reports/revenue?month=2027-3", null).statusCode());
    }

    @Test
    void occupancy() throws Exception {
        call("POST", "/reservations", body(202, CPF, "2027-03-10", "2027-03-12", 2, "STANDARD"));
